19\\u7ea6\\u675f\\u7684\\u5c11\\u6570\\u4e9a\\u7fa4\\uff08\\u5982\\u7f55\\u89c1\\u75be\\u75c5\\u4e9a\\u578b\\u3001\\u9ad8\\u9690\\u853d\\u6027\\u91d1\\u878d\\u6b3a\\u8bc8\\u7b56\\u7565\\u3001\\u7f55\\u89c1\\u8bbe\\u5907\\u6545\\u969c\\u5de5\\u51b5\\u7b49\\uff09\\u3002\\n\\n\\u672c\\u5b9e\\u9a8c\\u65b9\\u6848\\u6db5\\u76d6\\uff1a\\n1. **\\u7406\\u8bba\\u4f9d\\u636e\\uff08Rationale\\uff09**\\uff1a\\u9610\\u91ca\\u8868\\u683c\\u7a7a\\u95f4\\u7f55\\u89c1\\u6a21\\u5f0f\\u7684\\u51e0\\u4f55\\u7279\\u6027\\u53ca Docta \\u7684\\u6838\\u5fc3\\u62d3\\u6251/\\u5bc6\\u5ea6\\u5ea6\\u91cf\\u539f\\u7406\\uff1b\\n2. **\\u89c4\\u8303\\u5316\\u63a5\\u53e3\\u5b9a\\u4e49\\uff08API Specification\\uff09**\\uff1a\\u57fa\\u4e8e `RarePatternDetector` \\u7684\\u9762\\u5411\\u5bf9\\u8c61\\u8c03\\u7528\\u6807\\u51c6\\u4e0e\\u8f93\\u5165\\u8f93\\u51fa\\u89c4\\u8303\\uff1b\\n3. **\\u53cc\\u8f68\\u5b9e\\u9a8c\\u57fa\\u51c6\\uff08Dual Benchmarks\\uff09**\\uff1a\\u53d7\\u63a7\\u5408\\u6210\\u6ce8\\u5165\\u57fa\\u51c6\\uff08\\u5b9a\\u91cf\\u8bc4\\u4f30 Precision/Recall\\uff09\\u4e0e\\u771f\\u5b9e\\u8868\\u683c\\u4e1a\\u52a1\\u57fa\\u51c6\\uff08\\u5fae\\u7c07\\u53ef\\u89e3\\u91ca\\u6027\\u5206\\u6790\\uff09\\uff1b\\n4. **\\u5bf9\\u7167\\u4e0e\\u63a7\\u5236\\u7ec4\\u8bbe\\u8ba1\\uff08Controls & Baselines\\uff09**\\uff1a\\u4e0e Isolation Forest\\u3001LOF\\u3001OC-SVM \\u7b49\\u57fa\\u7ebf\\u53ca\\u6d88\\u878d\\u5b9e\\u9a8c\\u7684\\u5168\\u9762\\u5bf9\\u6bd4\\uff1b\\n5. **\\u4e0b\\u6e38\\u4efb\\u52a1\\u8d4b\\u80fd\\uff08Downstream DCAI Analysis\\uff09**\\uff1a\\u9a8c\\u8bc1\\u8bc6\\u522b\\u7f55\\u89c1\\u6a21\\u5f0f\\u5bf9\\u63d0\\u5347\\u4e0b\\u6e38\\u6a21\\u578b\\uff08XGBoost/LightGBM\\uff09\\u7a33\\u5065\\u6027\\u4e0e\\u6781\\u5c0f\\u7c7b\\u53ec\\u56de\\u7387\\u7684\\u6570\\u636e\\u4e2d\\u5fc3\\u4ef7\\u503c\\uff1b\\n6. **\\u5206\\u6790\\u8ba1\\u5212\\u4e0e\\u53ef\\u884c\\u6027\\u8bc4\\u4f30\\uff08Analysis Plan & Feasibility\\uff09**\\uff1a\\u5b8c\\u5907\\u7684\\u7edf\\u8ba1\\u68c0\\u9a8c\\u6807\\u51c6\\u4e0e\\u7b97\\u529b/\\u590d\\u6742\\u5ea6\\u9884\\u7b97\\u3002\\n\\n---\\n\\n## 2. \\u7406\\u8bba\\u4f9d\\u636e\\u4e0e\\u673a\\u5236\\u8bbe\\u8ba1\\uff08Theoretical Rationale\\uff09\\n\\n### 2.1 \\u8868\\u683c\\u6570\\u636e\\u4e2d\\u201c\\u7f55\\u89c1\\u6a21\\u5f0f\\u201d\\u7684\\u6570\\u5b66\\u8868\\u5f81\\n\\u8bbe\\u8868\\u683c\\u6570\\u636e\\u96c6\\u4e3a $\\\\mathcal{D} = \\\\{(\\\\mathbf{x}_i)\\\\}_{i=1}^N$\\uff0c\\u5176\\u4e2d\\u7279\\u5f81\\u5411\\u91cf $\\\\mathbf{x}_i \\\\in \\\\mathbb{R}^d$ \\u5305\\u542b\\u8fde\\u7eed\\u578b\\u53d8\\u91cf $\\\\mathcal{X}_{num}$ \\u548c\\u79bb\\u6563\\u7c7b\\u522b\\u578b\\u53d8\\u91cf $\\\\mathcal{X}_{cat}$\\u3002\\n- **\\u5168\\u5c40\\u79bb\\u7fa4\\u70b9\\uff08Outlier/Noise\\uff09**\\uff1a\\u6ee1\\u8db3\\u5c40\\u90e8\\u5bc6\\u5ea6\\u6781\\u4f4e\\u4e14\\u4e0d\\u5177\\u5907\\u5b50\\u7fa4\\u805a\\u96c6\\u6027\\uff1a$\\\\forall r > 0, |\\\\mathcal{B}_r(\\\\mathbf{x}_i)| \\\\approx 1$\\u3002\\n- **\\u7f55\\u89c1\\u6a21\\u5f0f\\uff08Rare Patterns / Micro-Clusters\\uff09**\\uff1a\\u5b58\\u5728\\u5c0f\\u89c4\\u6a21\\u5b50\\u96c6 $\\\\mathcal{S}_{rare} \\\\subset \\\\mathcal{D}$\\uff0c\\u5176\\u6837\\u672c\\u5bb9\\u91cf\\u5360\\u6bd4 $\\\\frac{|\\\\mathcal{S}_{rare}|}{N} \\\\le \\\\alpha$\\uff08\\u901a\\u5e38 $\\\\alpha \\\\in [0.1\\\\%, 5\\\\%]$\\uff09\\uff0c\\u4e14\\u5728\\u7279\\u5b9a\\u7684\\u5c40\\u90e8\\u5b50\\u7a7a\\u95f4\\u6216\\u6d41\\u5f62 $\\\\mathcal{M}_{sub}$ \\u4e0a\\u6ee1\\u8db3\\u5c40\\u90e8\\u805a\\u96c6\\u6027\\u4e0e\\u76f8\\u5bf9\\u4f4e\\u9891\\u6027\\uff1a\\n  $$p(\\\\mathbf{x}) \\\\ll \\\\mathbb{E}_{\\\\mathbf{x} \\\\sim \\\\mathcal{D}}[p(\\\\mathbf{x})], \\\\quad \\\\text{\\u4f46} \\\\quad \\\\mathrm{dist}(\\\\mathbf{x}_i, \\\\mathbf{x}_j) \\\\le \\\\epsilon \\\\quad (\\\\forall \\\\mathbf{x}_i, \\\\mathbf{x}_j \\\\in \\\\mathcal{S}_{rare})$$\\n\\n### 2.2 Docta \\u7684\\u6838\\u5fc3\\u68c0\\u6d4b\\u673a\\u5236\\nDocta \\u5728\\u8868\\u683c\\u8d28\\u91cf\\u68c0\\u6d4b\\u4e2d\\u91c7\\u7528\\u591a\\u5c42\\u6b21\\u6df7\\u5408\\u68c0\\u6d4b\\u8303\\u5f0f\\uff1a\\n1. **\\u5f02\\u6784\\u7279\\u5f81\\u6d41\\u5f62\\u6620\\u5c04\\uff08Heterogeneous Feature Space Mapping\\uff09**\\uff1a\\n   \\u901a\\u8fc7\\u5206\\u4f4d\\u6570\\u53d8\\u6362\\uff08Quantile Transform\\uff09\\u4f7f\\u8fde\\u7eed\\u7279\\u5f81\\u65e0\\u91cf\\u7eb2\\u5316\\uff0c\\u5bf9\\u79bb\\u6563\\u7279\\u5f81\\u901a\\u8fc7 Target Encoding\\u3001One-Hot \\u6216\\u57fa\\u4e8e\\u5d4c\\u5165\\u7684\\u9ad8\\u7ef4\\u5411\\u91cf\\u5316\\uff0c\\u4f7f\\u591a\\u5c5e\\u6027\\u6df7\\u5408\\u8ddd\\u79bb\\uff08\\u5982\\u52a0\\u6743\\u6b27\\u6c0f\\u8ddd\\u79bb\\u6216 Gower \\u8ddd\\u79bb\\uff09\\u4fdd\\u6301\\u51e0\\u4f55\\u771f\\u5b9e\\u6027\\u3002\\n2. **\\u90bb\\u57df\\u62d3\\u6251\\u4e0e\\u76f8\\u5bf9\\u5bc6\\u5ea6\\u4f30\\u8ba1\\uff08Local Topology & Relative Density Scoring\\uff09**\\uff1a\\n   \\u57fa\\u4e8e\\u81ea\\u9002\\u5e94\\u8fd1\\u90bb\\u56fe\\uff08$k$-Nearest Neighbors Graph\\uff09\\uff0c\\u8ba1\\u7b97\\u76f8\\u5bf9\\u5bc6\\u5ea6\\u6307\\u6570\\u6216\\u5c40\\u90e8\\u53ef\\u8fbe\\u5bc6\\u5ea6\\uff08Local Reachability Density, LRD\\uff09\\u3002\\u4e0e\\u5168\\u5c40\\u5bc6\\u5ea6\\u76f8\\u6bd4\\uff0c\\u76f8\\u5bf9\\u5bc6\\u5ea6\\u80fd\\u591f\\u81ea\\u9002\\u5e94\\u4e0d\\u540c\\u7279\\u5f81\\u533a\\u57df\\u672c\\u8eab\\u7684\\u5bc6\\u5ea6\\u65b9\\u5dee\\uff0c\\u907f\\u514d\\u56e0\\u5bc6\\u96c6\\u533a\\u57df\\u8fb9\\u7f18\\u6837\\u672c\\u88ab\\u8bef\\u5224\\u800c\\u6f0f\\u68c0\\u7a00\\u758f\\u533a\\u57df\\u7684\\u805a\\u96c6\\u6027\\u5fae\\u7c07\\u3002\\n3. **\\u5b50\\u7a7a\\u95f4\\u4e0e\\u9694\\u79bb\\u5ea6\\u91cf\\uff08Subspace & Isolation Mechanism\\uff09**\\uff1a\\n   \\u7ed3\\u5408\\u591a\\u53d8\\u91cf\\u4ea4\\u4e92\\u6811\\u7ed3\\u6784\\uff0c\\u6d4b\\u91cf\\u5c06\\u6837\\u672c\\u5b8c\\u5168\\u9694\\u79bb\\u6240\\u9700\\u7684\\u5e73\\u5747\\u8def\\u5f84\\u6df1\\u5ea6\\uff08Average Path Length\\uff09\\uff0c\\u6216\\u5229\\u7528\\u6df1\\u5ea6\\u81ea\\u7f16\\u7801\\u5668\\uff08Tabular AutoEncoder\\uff09\\u7684\\u91cd\\u6784\\u6b8b\\u5dee\\u4e0e\\u6f5c\\u5728\\u7a7a\\u95f4\\u4f4e\\u7ef4\\u5206\\u5e03\\uff0c\\u8d4b\\u4e88\\u6bcf\\u4e2a\\u6837\\u672c\\u4e00\\u4e2a\\u6807\\u51c6\\u5316\\u7684**\\u7f55\\u89c1\\u5ea6\\u5f97\\u5206\\uff08Rarity Score $s_i \\\\in [0, 1]$\\uff09**\\u3002\\n4. **\\u7edf\\u8ba1\\u6781\\u503c\\u7406\\u8bba\\u4e0e\\u81ea\\u9002\\u5e94\\u9608\\u503c\\u5206\\u4f4d\\uff08EVT Thresholding\\uff09**\\uff1a\\n   \\u5229\\u7528\\u6781\\u503c\\u7406\\u8bba\\uff08Extreme Value Theory\\uff09\\u6216\\u9884\\u8bbe\\u7684\\u6c61\\u67d3\\u7387\\u5148\\u9a8c\\uff08`contamination`\\uff09\\uff0c\\u81ea\\u9002\\u5e94\\u5212\\u5206\\u7f55\\u89c1\\u6a21\\u5f0f\\u5019\\u9009\\u96c6 $\\\\hat{\\\\mathcal{S}}_{rare} = \\\\{\\\\mathbf{x}_i \\\\mid s_i \\\\ge \\\\tau\\\\}$\\u3002\\n\\n---\\n\\n## 3. \\u529f\\u80fd\\u63a5\\u53e3\\u4e0e API \\u89c4\\u8303\\uff08API Specification & Pipeline\\uff09\\n\\n\\u4e3a\\u786e\\u4fdd\\u5b9e\\u9a8c\\u8bbe\\u8ba1\\u7684\\u53ef\\u64cd\\u4f5c\\u6027\\u4e0e\\u4e00\\u81f4\\u6027\\uff0c\\u5b9a\\u4e49 Docta \\u98ce\\u683c\\u7684\\u9ad8\\u5c42\\u6807\\u51c6\\u63a5\\u53e3 `RarePatternDetector`\\u3002\\n\\n### 3.1 \\u6838\\u5fc3\\u7c7b\\u4e0e\\u65b9\\u6cd5\\u7b7e\\u540d\\n\\n```python\\nfrom typing import Dict, List, Optional, Tuple, Union\\nimport numpy as np\\nimport pandas as pd\\n\\nclass RarePatternDetector:\\n    \\\"\\\"\\\"Docta \\u8868\\u683c\\u7f55\\u89c1\\u6a21\\u5f0f\\u68c0\\u6d4b\\u5668\\n\\n    Parameters\\n    ----------\\n    method : str, default='knn_density'\\n        \\u5e95\\u5c42\\u68c0\\u6d4b\\u673a\\u5236\\uff0c\\u53ef\\u9009 ['knn_density', 'isolation', 'subspace_cluster', 'autoencoder']\\u3002\\n    contamination : float, default=0.01\\n        \\u9884\\u671f\\u6570\\u636e\\u96c6\\u4e2d\\u7f55\\u89c1\\u6a21\\u5f0f\\u7684\\u6bd4\\u4f8b\\u6bd4\\u4f8b\\u9608\\u503c\\uff08\\u5982 0.01 \\u8868\\u793a 1%\\uff09\\u3002\\n    n_neighbors : int, default=15\\n        \\u5c40\\u90e8\\u62d3\\u6251/\\u5bc6\\u5ea6\\u8ba1\\u7b97\\u7684\\u8fd1\\u90bb\\u6570\\u53c2\\u6570 k\\u3002\\n    metric : str, default='euclidean'\\n        \\u8ddd\\u79bb\\u5ea6\\u91cf\\u6807\\u51c6\\uff0c\\u652f\\u6301 'euclidean', 'manhattan', 'gower'\\u3002\\n    categorical_features : Optional[List[Union[str, int]]], default=None\\n        \\u79bb\\u6563\\u7c7b\\u522b\\u7279\\u5f81\\u5217\\u540d\\u6216\\u5217\\u7d22\\u5f15\\u5217\\u8868\\u3002\\n    random_state : int, default=42\\n        \\u968f\\u673a\\u79cd\\u5b50\\uff0c\\u4fdd\\u8bc1\\u5b9e\\u9a8c\\u53ef\\u590d\\u73b0\\u3002\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        method: str = \\\"knn_density\\\",\\n        contamination: float = 0.01,\\n        n_neighbors: int = 15,\\n        metric: str = \\\"euclidean\\\",\\n        categorical_features: Optional[List[Union[str, int]]] = None,\\n        random_state: int = 42,\\n    ):\\n        self.method = method\\n        self.contamination = contamination\\n        self.n_neighbors = n_neighbors\\n        self.metric = metric\\n        self.categorical_features = categorical_features\\n        self.random_state = random_state\\n\\n        # \\u5185\\u90e8\\u72b6\\u6001\\u5c5e\\u6027\\n        self.threshold_: float = 0.0\\n        self.feature_names_: List[str] = []\\n        self.is_fitted_: bool = False\\n\\n    def fit(self, X: Union[pd.DataFrame, np.ndarray], y: Optional[np.ndarray] = None) -> \\\"RarePatternDetector\\\":\\n        \\\"\\\"\\\"\\u5728\\u7279\\u5f81\\u77e9\\u9635 X \\u4e0a\\u62df\\u5408\\u80cc\\u666f\\u6570\\u636e\\u5206\\u5e03\\u3002\\n\\n        Parameters\\n        ----------\\n        X : pd.DataFrame \\u6216 np.ndarray, \\u5f62\\u72b6\\u4e3a (n_samples, n_features)\\n        y : \\u53ef\\u9009\\u7684\\u76ee\\u6807\\u53d8\\u91cf\\uff0c\\u65e0\\u76d1\\u7763\\u6a21\\u5f0f\\u4e0b\\u4e3a None\\u3002\\n        \\\"\\\"\\\"\\n        ...\\n        self.is_fitted_ = True\\n        return self\\n\\n    def score_rarity(self, X: Union[pd.DataFrame, np.ndarray]) -> np.ndarray:\\n        \\\"\\\"\\\"\\u8ba1\\u7b97\\u6bcf\\u4e2a\\u6837\\u672c\\u7684\\u8fde\\u7eed\\u7f55\\u89c1\\u5ea6\\u6253\\u5206\\uff08Rarity Score\\uff09\\u3002\\n\\n        Returns\\n        -------\\n        scores : np.ndarray, \\u5f62\\u72b6\\u4e3a (n_samples,), \\u5206\\u503c\\u901a\\u5e38\\u5f52\\u4e00\\u5316\\u5728 [0, 1] \\u4e4b\\u95f4\\uff0c\\u5206\\u503c\\u8d8a\\u5927\\u4ee3\\u8868\\u8d8a\\u7f55\\u89c1\\u3002\\n        \\\"\\\"\\\"\\n        ...\\n        return np.array([])\\n\\n    def predict(self, X: Union[pd.DataFrame, np.ndarray]) -> np.ndarray:\\n        \\\"\\\"\\\"\\u57fa\\u4e8e\\u62df\\u5408\\u9608\\u503c\\u4e8c\\u503c\\u5224\\u5b9a\\u662f\\u5426\\u4e3a\\u7f55\\u89c1\\u6a21\\u5f0f\\u6837\\u672c\\u3002\\n\\n        Returns\\n        -------\\n        is_rare : np.ndarray (bool), True \\u8868\\u793a\\u4e3a\\u8bc6\\u522b\\u51fa\\u7684\\u7f55\\u89c1\\u6a21\\u5f0f\\u3002\\n        \\\"\\\"\\\"\\n        scores = self.score_rarity(X)\\n        return scores >= self.threshold_\\n\\n    def fit_predict(self, X: Union[pd.DataFrame, np.ndarray], y: Optional[np.ndarray] = None) -> np.ndarray:\\n        \\\"\\\"\\\"\\u62df\\u5408\\u5e76\\u5728\\u540c\\u4e00\\u6570\\u636e\\u4e0a\\u9884\\u6d4b\\u7f55\\u89c1\\u6a21\\u5f0f\\u63a9\\u7801\\u3002\\\"\\\"\\\"\\n        return self.fit(X, y).predict(X)\\n\\n    def explain(\\n        self, X: Union[pd.DataFrame, np.ndarray], indices: Optional[List[int]] = None, top_k_features: int = 3\\n    ) -> pd.DataFrame:\\n        \\\"\\\"\\\"\\u5bf9\\u88ab\\u8bc6\\u522b\\u4e3a\\u7f55\\u89c1\\u6a21\\u5f0f\\u7684\\u6837\\u672c\\u8f93\\u51fa\\u7279\\u5f81\\u5f52\\u56e0\\u89e3\\u91ca\\u3002\\n\\n        Returns\\n        -------\\n        explanation_df : pd.DataFrame\\n            \\u5305\\u542b\\u6837\\u672c\\u7d22\\u5f15\\u3001\\u4e3b\\u8981\\u504f\\u79bb\\u7279\\u5f81\\u5217\\u3001\\u7279\\u5f81\\u5c40\\u90e8\\u7f55\\u89c1\\u8d21\\u732e\\u5ea6\\uff08Shapley/Deviation Score\\uff09\\u3002\\n        \\\"\\\"\\\"\\n        ...\\n        return pd.DataFrame()\\n```\\n\\n### 3.2 \\u5178\\u578b\\u6570\\u636e\\u7ba1\\u9053\\u5de5\\u4f5c\\u6d41\\u5b9e\\u73b0\\u793a\\u4f8b\\n\\n```python\\n# \\u5178\\u578b\\u4f7f\\u7528\\u6d41\\u7a0b\\nfrom docta.tabular import RarePatternDetector\\nimport pandas as pd\\n\\n# 1. \\u52a0\\u8f7d\\u8868\\u683c\\u6570\\u636e\\ndf = pd.read_csv(\\\"tabular_benchmark.csv\\\")\\ncat_cols = [\\\"occupation\\\", \\\"workclass\\\", \\\"marital_status\\\"]\\n\\n# 2. \\u521d\\u59cb\\u5316\\u68c0\\u6d4b\\u5668\\ndetector = RarePatternDetector(\\n    method=\\\"knn_density\\\",\\n    contamination=0.01,  # \\u8bbe\\u5b9a 1% \\u7f55\\u89c1\\u6bd4\\u4f8b\\n    n_neighbors=20,\\n    categorical_features=cat_cols,\\n    random_state=42,\\n)\\n\\n# 3. \\u62df\\u5408\\u4e0e\\u8ba1\\u7b97\\u7a00\\u6709\\u5ea6\\u5f97\\u5206\\ndetector.fit(df)\\nrarity_scores = detector.score_rarity(df)\\nrare_mask = detector.predict(df)\\n\\n# 4. \\u83b7\\u53d6\\u7f55\\u89c1\\u6a21\\u5f0f\\u6837\\u672c\\u4e0e\\u5fae\\u7c07\\u89e3\\u91ca\\nrare_indices = np.where(rare_mask)[0]\\nexplanations = detector.explain(df, indices=rare_indices[:10])\\n```\\n\\n---\\n\\n## 4. \\u5b9e\\u9a8c\\u573a\\u666f\\u4e0e\\u53cc\\u8f68\\u57fa\\u51c6\\u6784\\u5efa\\uff08Experimental Benchmarks\\uff09\\n\\n\\u4e3a\\u540c\\u65f6\\u6ee1\\u8db3\\u201c\\u7cbe\\u51c6\\u91cf\\u5316\\u8bc4\\u6d4b\\u201d\\u4e0e\\u201c\\u5b9e\\u9645\\u4e1a\\u52a1\\u53ef\\u6cdb\\u5316\\u6027\\u201d\\uff0c\\u5b9e\\u9a8c\\u6784\\u5efa\\u53cc\\u8f68\\u57fa\\u51c6\\uff1a\\n\\n### \\u57fa\\u51c6 A\\uff1a\\u53d7\\u63a7\\u5408\\u6210\\u4e0e\\u534a\\u5408\\u6210\\u8868\\u683c\\u6ce8\\u5165\\u96c6\\uff08Quantitative Injected Benchmark\\uff09\\n1. **\\u80cc\\u666f\\u5206\\u5e03\\u6784\\u5efa**\\uff1a\\n   - \\u9009\\u53d6\\u5177\\u6709\\u5df2\\u77e5\\u8fde\\u7eed\\u548c\\u7c7b\\u522b\\u7279\\u5f81\\u7684\\u771f\\u5b9e\\u8868\\u683c\\u4f5c\\u4e3a\\u80cc\\u666f\\u5206\\u5e03\\uff08\\u5982 UCI Adult Census \\u6216 California Housing\\uff0c\\u6837\\u672c\\u91cf $N = 30,000$\\uff09\\u3002\\n2. **\\u591a\\u6a21\\u5f0f\\u53d7\\u63a7\\u7f55\\u89c1\\u6a21\\u5f0f\\u6ce8\\u5165\\uff08Injected Scenarios\\uff09**\\uff1a\\n   - **Scenario 1\\uff08\\u9ad8\\u7ef4\\u7a00\\u758f\\u5fae\\u7c07\\uff0cMicro-Clusters\\uff09**\\uff1a\\u6ce8\\u5165 $K_m=3$ \\u4e2a\\u8d85\\u7d27\\u51d1\\u9ad8\\u65af\\u5b50\\u7fa4\\uff0c\\u6bcf\\u4e2a\\u5fae\\u7c07\\u5305\\u542b\\u6837\\u672c\\u91cf $N_c = 15 \\\\sim 30$\\uff08\\u603b\\u5360\\u6bd4\\u5206\\u522b\\u4e3a $0.5\\\\%, 1.0\\\\%, 3.0\\\\%$\\uff09\\uff0c\\u5728\\u7279\\u5b9a\\u7279\\u5f81\\u5b50\\u96c6\\u4e0a\\u5177\\u6709\\u7d27\\u5bc6\\u805a\\u96c6\\u4f46\\u5728\\u5168\\u7a7a\\u95f4\\u5904\\u4e8e\\u6781\\u4f4e\\u5bc6\\u5ea6\\u533a\\u57df\\u3002\\n   - **Scenario 2\\uff08\\u591a\\u5c5e\\u6027\\u8054\\u5408\\u7f55\\u89c1\\u89c4\\u5219\\uff0cRare Combinatorial Rules\\uff09**\\uff1a\\u4f8b\\u5982\\u6784\\u9020\\u79bb\\u6563\\u4e0e\\u8fde\\u7eed\\u53d8\\u91cf\\u7684\\u6781\\u7aef\\u7f55\\u89c1\\u4ea4\\u53c9\\uff08\\u5982 `Age < 18 & Income > 100k & Education = Doctorate`\\uff09\\uff0c\\u5355\\u53d8\\u91cf\\u8fb9\\u7f18\\u5206\\u5e03\\u6b63\\u5e38\\uff0c\\u4f46\\u8054\\u5408\\u6982\\u7387\\u6781\\u4f4e\\u3002\\n   - **Scenario 3\\uff08\\u80cc\\u666f\\u9ad8\\u65af\\u968f\\u673a\\u566a\\u58f0\\u6270\\u52a8\\uff0cUnstructured Noise\\uff09**\\uff1a\\u6ce8\\u5165\\u7b49\\u91cf\\u5355\\u70b9\\u968f\\u673a\\u5747\\u5300\\u767d\\u566a\\u58f0\\u4f5c\\u4e3a\\u8d1f\\u63a7\\uff0c\\u9a8c\\u8bc1\\u68c0\\u6d4b\\u5668\\u533a\\u5206\\u201c\\u7ed3\\u6784\\u5316\\u7f55\\u89c1\\u6a21\\u5f0f\\u201d\\u4e0e\\u201c\\u968f\\u673a\\u810f\\u6570\\u636e\\u201d\\u7684\\u80fd\\u529b\\u3002\\n3. **\\u771f\\u503c\\u6807\\u8bb0\\uff08Ground Truth\\uff09**\\uff1a\\n   \\u6bcf\\u4e2a\\u6837\\u672c\\u6807\\u6ce8\\u7cbe\\u786e\\u7684\\u5e03\\u5c14\\u6807\\u7b7e $y_{\\\\mathrm{rare}} \\\\in \\\\{0, 1\\\\}$\\uff0c\\u7528\\u4e8e\\u4e25\\u683c\\u5ea6\\u91cf\\u68c0\\u6d4b\\u6307\\u6807\\u3002\\n\\n### \\u57fa\\u51c6 B\\uff1a\\u771f\\u5b9e\\u9886\\u57df\\u5178\\u578b\\u8868\\u683c\\u6570\\u636e\\u96c6\\uff08Real-World Business Benchmarks\\uff09\\n1. **\\u91d1\\u878d\\u6b3a\\u8bc8/\\u98ce\\u9669\\u4ea4\\u6613\\u6570\\u636e\\uff08\\u5982 Credit Card Fraud Detection / IEEE-CIS Fraud Benchmark\\uff09**\\uff1a\\n   - \\u7279\\u70b9\\uff1a\\u6837\\u672c\\u91cf\\u5927\\uff08$> 200,000$\\uff09\\uff0c\\u6807\\u7b7e\\u9ad8\\u5ea6\\u503e\\u659c\\uff08\\u6b63\\u7c7b\\u5360\\u6bd4 $\\\\approx 0.17\\\\%$\\uff09\\u3002\\n   - \\u8bc4\\u6d4b\\u4fa7\\u91cd\\uff1a\\u5c06\\u5929\\u7136\\u5c11\\u6570\\u7c7b\\u4ea4\\u6613\\u4f5c\\u4e3a\\u5929\\u7136\\u7f55\\u89c1\\u6a21\\u5f0f\\uff0c\\u68c0\\u9a8c Docta \\u5728\\u65e0\\u76d1\\u7763\\u6761\\u4ef6\\u4e0b\\u7684\\u65e0\\u6807\\u7b7e\\u68c0\\u51fa\\u7387\\uff0c\\u5e76\\u5206\\u6790\\u68c0\\u51fa\\u7684\\u7f55\\u89c1\\u6a21\\u5f0f\\u662f\\u5426\\u5bf9\\u5e94\\u65b0\\u578b\\u56e2\\u4f19\\u6b3a\\u8bc8\\u7279\\u5f81\\u7ec4\\u5408\\u3002\\n2. **\\u591a\\u7c7b\\u522b\\u7f55\\u89c1\\u5b50\\u7fa4\\u6570\\u636e\\uff08\\u5982 Forest CoverType \\u7f55\\u89c1\\u5730\\u8c8c\\u4e9a\\u578b / \\u533b\\u7597\\u91cd\\u75c7\\u60a3\\u8005\\u4e9a\\u578b\\uff09**\\uff1a\\n   - \\u7279\\u70b9\\uff1a\\u5305\\u542b\\u4e30\\u5bcc\\u7684\\u6570\\u503c\\u578b\\u5730\\u5f62/\\u751f\\u7406\\u6307\\u6807\\u4e0e\\u591a\\u79cd\\u79bb\\u6563\\u7c7b\\u578b\\uff0c\\u5b58\\u5728\\u5360\\u6bd4 $< 0.5\\\\%$ \\u7684\\u6781\\u5c0f\\u7c7b\\u522b\\u3002\\n   - \\u8bc4\\u6d4b\\u4fa7\\u91cd\\uff1a\\u8bc4\\u4f30\\u68c0\\u6d4b\\u51fa\\u7684\\u7f55\\u89c1\\u6a21\\u5f0f\\u5728\\u4e1a\\u52a1\\u5fae\\u7c07\\u4e0a\\u7684\\u5bf9\\u5e94\\u7cbe\\u5ea6\\u53ca\\u53ef\\u89e3\\u91ca\\u6027\\u3002\\n\\n---\\n\\n## 5. \\u5bf9\\u7167\\u4e0e\\u63a7\\u5236\\u7ec4\\u8bbe\\u8ba1\\uff08Controls & Baselines\\uff09\\n\\n### 5.1 \\u5bf9\\u7167\\u6a21\\u578b\\u5e93\\uff08Baseline Methods\\uff09\\n\\u5728\\u76f8\\u540c\\u9884\\u5904\\u7406\\uff08\\u7edf\\u4e00 One-Hot \\u79bb\\u6563\\u7f16\\u7801\\u3001RobustScaler \\u6570\\u503c\\u7f29\\u653e\\uff09\\u7ba1\\u9053\\u4e0b\\uff0c\\u914d\\u7f6e\\u4ee5\\u4e0b\\u5bf9\\u7167\\u7b97\\u6cd5\\uff1a\\n1. **Random Scoring Baseline**\\uff1a\\u968f\\u673a\\u751f\\u6210 $[0, 1]$ \\u5206\\u503c\\uff0c\\u4f5c\\u4e3a\\u7edf\\u8ba1\\u4e0b\\u754c\\u3002\\n2. **Isolation Forest (iForest)**\\uff1a\\u57fa\\u4e8e\\u968f\\u673a\\u6b63\\u4ea4\\u7279\\u5f81\\u5207\\u5206\\u7684\\u4f20\\u7edf\\u57fa\\u4e8e\\u6811\\u7684\\u9694\\u79bb\\u7b97\\u6cd5\\u3002\\n3. **Local Outlier Factor (LOF)**\\uff1a\\u7ecf\\u5178\\u7684\\u57fa\\u4e8e $k$ \\u8fd1\\u90bb\\u5c40\\u90e8\\u53ef\\u8fbe\\u5bc6\\u5ea6\\u7684\\u79bb\\u7fa4\\u68c0\\u6d4b\\u7b97\\u6cd5\\u3002\\n4. **One-Class SVM (OC-SVM)**\\uff1a\\u57fa\\u4e8e RBF \\u6838\\u5c06\\u6570\\u636e\\u6620\\u5c04\\u5230\\u9ad8\\u7ef4\\u5e0c\\u5c14\\u4f2f\\u7279\\u7a7a\\u95f4\\u7684\\u8d85\\u7403\\u9762\\u8fb9\\u754c\\u68c0\\u6d4b\\u7b97\\u6cd5\\u3002\\n5. **PCA/AE Reconstruction Residuals**\\uff1a\\u57fa\\u4e8e\\u65e0\\u76d1\\u7763\\u964d\\u7ef4\\u4e0e\\u91cd\\u6784\\u6b8b\\u5dee\\u7684\\u8868\\u793a\\u5b66\\u4e60\\u57fa\\u7ebf\\u3002\\n\\n### 5.2 \\u6d88\\u878d\\u5b9e\\u9a8c\\u8bbe\\u8ba1\\uff08Ablation Studies\\uff09\\n\\u4e3a\\u5256\\u6790 Docta \\u5404\\u8bbe\\u8ba1\\u6a21\\u5757\\u5bf9\\u7f55\\u89c1\\u6a21\\u5f0f\\u8bc6\\u522b\\u7684\\u8d21\\u732e\\uff0c\\u8bbe\\u8ba1\\u4ee5\\u4e0b\\u6d88\\u878d\\u6761\\u4ef6\\uff1a\\n1. **\\u62d3\\u6251\\u8ddd\\u79bb\\u5ea6\\u91cf\\u6d88\\u878d**\\uff1a\\u5bf9\\u6bd4 Euclidean \\u8ddd\\u79bb\\u3001Manhattan \\u8ddd\\u79bb\\u3001\\u4e0e\\u4e13\\u95e8\\u9002\\u914d\\u6df7\\u5408\\u7c7b\\u578b\\u7684 Gower \\u8ddd\\u79bb\\u6216 Learned Metric\\u3002\\n2. **\\u8fd1\\u90bb\\u89c4\\u6a21\\u654f\\u611f\\u6027\\uff08Neighbor Scaling $k$\\uff09**\\uff1a\\u8bbe\\u7f6e $k \\\\in \\\\{5, 10, 15, 20, 50, 100\\\\}$\\uff0c\\u89c2\\u5bdf\\u5c0f\\u5fae\\u7c07\\u5728\\u4e0d\\u540c $k$ \\u53d6\\u503c\\u4e0b\\u7684\\u201c\\u6df9\\u6ca1\\u6548\\u5e94\\uff08Swamping\\uff09\\u201d\\u4e0e\\u201c\\u63a9\\u853d\\u6548\\u5e94\\uff08Masking\\uff09\\u201d\\u3002\\n3. **\\u6c61\